const cp = require("child_process");
// process.exitCode and 'exit' at a program's natural end: each case runs as a child of this program.
// The same package under Node.js prints the same.
const cases = {
  code() { process.exitCode = 4; },
  listener() {
    process.on("exit", (code) => { console.log("exit event", code); process.exitCode = 9; });
    process.exitCode = 3;
  },
  timer() { setTimeout(() => { process.exitCode = 6; }, 20); },
  none() {},
};
module.exports = function run() {
  const which = process.env.TOV_EXIT_CASE;
  if (which) return cases[which]();
  for (const c of Object.keys(cases)) {
    const r = cp.spawnSync(process.execPath, process.execArgv.concat(process.argv.slice(1)), { env: { ...process.env, TOV_EXIT_CASE: c }, encoding: "utf8" });
    console.log(c, r.status, JSON.stringify(r.stdout));
  }
};
